def solve(I):
    Hh,Ww=len(I),len(I[0])
    marks=[(i,j,I[i][j]) for i in range(Hh) for j in range(Ww) if I[i][j]]
    offs={1:(-1,2),2:(0,-4),3:(3,0),6:(0,-6)}
    D={1:(0,1),2:(0,-1),3:(1,0),6:(-1,0)}
    O=[r[:] for r in I]
    # per mark: copy + ray cells between mark and copy (exclusive of copy)
    info=[]
    for i,j,c in marks:
        off=offs[c]; sy=(off[0]>0)-(off[0]<0); sx=(off[1]>0)-(off[1]<0)
        ti,tj=i+off[0],j+off[1]
        k=1; cells=[]
        while (i+sy*k,j+sx*k)!=(ti,tj):
            ni,nj=i+sy*k,j+sx*k
            cells.append((ni,nj)); k+=1
        info.append((c,(i,j),(ti,tj),cells))
    seg=[set(cells) for _,_,_,cells in info]
    # crossings: cell shared by >=2 different rays' segments
    pts=[]  # (cell,colors)
    for idx,cs_ in enumerate(seg):
        pts.append(list(cs_))
    crossing=set()
    for a in range(len(info)):
        for b in range(a+1,len(info)):
            ca=(info[a][0]); cb=info[b][0]
            if ca==cb: continue
            sA=set(info[a][3]); sB=set(info[b][3])
            inter=sA&sB
            for cell in inter:
                crossing.add(cell)
    for i,j in crossing:
        O[i][j]=4
    for c,pos,cp,cells in info:
        for i,j in cells:
            if (i,j) not in crossing: O[i][j]=5
    return O
