D={1:(0,1),2:(0,-1),3:(1,0),6:(-1,0)}
L={1:2,3:2,2:3,6:5}
def f(I):
    H=len(I);W=len(I[0])
    pts=[(i,j,I[i][j]) for i in range(H) for j in range(W) if I[i][j]]
    out=[r[:] for r in I]
    for i,j,c in pts:
        dd=D[c]; d=L[c]
        for k in range(1,d+1):
            ni,nj=i+dd[0]*k,j+dd[1]*k
            if 0<=ni<H and 0<=nj<W: out[ni][nj]=5
            else: break
        e=(i+dd[0]*d,j+dd[1]*d)
        ti,tj=e
        # find orthogonal neighbor of end that is farthest from all other dots
        best=None
        for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            t=(e[0]+di,e[1]+dj)
            if 0<=t[0]<H and 0<=t[1]<W and out[t[0]][t[1]]==0:
                # distance from each other dot (to that candidate cell)
                tot=sum(abs(t[0]-p[0])+abs(t[1]-p[1]) for p in pts if p!=(i,j,c))
                if best is None or tot>best[0]: best=(tot,t)
        if best:
            ti,tj=best[1]
            out[ti][tj]=c
    return out
